from pathlib import Path
root=Path(__file__).resolve().parent
checks=[]
def check(label,ok): checks.append((label,bool(ok)))
entity=(root/'src/scheduling/schedule-exception.entity.ts').read_text()
dto=(root/'src/scheduling/dto/create-schedule-exception.dto.ts').read_text()
docsvc=(root/'src/scheduling/scheduling.service.ts').read_text()
docctrl=(root/'src/scheduling/scheduling.controller.ts').read_text()
facsvc=(root/'src/facilities/facilities.service.ts').read_text()
facctrl=(root/'src/facilities/facilities.controller.ts').read_text()
slot=(root/'src/facilities/facility-slot.entity.ts').read_text()
app=(root/'src/app.module.ts').read_text(); ds=(root/'src/database/data-source.ts').read_text()
mod=(root/'src/facilities/facilities.module.ts').read_text(); schedmod=(root/'src/scheduling/scheduling.module.ts').read_text()
mg=(root/'src/database/migrations/1732600000000-CreateScheduleExceptions.ts').read_text()
docs=(root/'docs/phase-v26-exceptional-closures.md').read_text()
apt=(root/'src/appointments/appointments.service.ts').read_text()
facmodule=(root/'src/appointments/appointments.module.ts').read_text()
check('shared exception entity supports doctor and facility owner scopes', all(x in entity for x in ['WeeklyScheduleOwnerType','ownerType','ownerId','serviceId','startsAt','endsAt','isActive']))
check('exception DTO validates ISO timestamps, timezone, optional service and reason', all(x in dto for x in ['@IsISO8601','@Matches(ISO_WITH_OFFSET)','@IsUUID','@MaxLength(240)']))
check('doctor can create, list, and restore exceptional closures', all(x in docsvc for x in ['createDoctorException','myDoctorExceptions','removeDoctorException']))
check('doctor closure endpoints are authenticated and doctor-role protected', all(x in docctrl for x in ['me/schedule-exceptions','@Roles(UserRole.DOCTOR)']))
check('doctor open slots overlapping closures are closed', 'status:SlotStatus.CLOSED' in docsvc and 'affectedSlotIds:openSlots.map' in docsvc)
check('doctor cannot create or reopen slots inside active closures', 'ensureNoDoctorException' in docsvc and 'ensureSlotFitsSchedule(userId,x.range[0],x.range[1])' in docsvc)
check('confirmed doctor appointments are reported and not cancelled', 'affectedConfirmedAppointments' in docsvc and 'لم يتم إلغاؤها' in docsvc)
check('facility owner can create, list, and restore closures', all(x in facsvc for x in ['createScheduleException','ownerScheduleExceptions','restoreScheduleException']))
check('facility closure endpoints require owner role', all(x in facctrl for x in ['owner/:id/schedule-exceptions','@Roles(UserRole.OWNER)']))
check('facility closures can target one service or the whole center', 'dto.serviceId??null' in facsvc and 'e.serviceId IS NULL OR e.serviceId=:serviceId' in facsvc)
check('facility slots have a separate closed status', "CLOSED='closed'" in slot)
check('facility slot generation skips active exceptions', 'activeExceptions.some' in facsvc)
check('facility new slots are rejected during active closures', 'هذه الفترة معطّلة مؤقتاً' in facsvc)
check('requested and confirmed facility bookings are reported without auto-cancellation', 'affectedBookings' in facsvc and 'لم يتم إلغاؤها' in facsvc)
check('restoring a closure only reopens future slots still valid under current schedules', 'const blocked=others.some' in facsvc and 'await this.ensureFacilitySlotFitsSchedule' in facsvc and 'await this.ensureSlotFitsSchedule' in docsvc)
check('doctor appointment cancellation does not reopen a slot during an active closure', 'const closure=await manager.getRepository(ScheduleException)' in apt and 'closure ? SlotStatus.CLOSED : SlotStatus.OPEN' in apt)
check('facility cancellation or rejection keeps a slot closed during an active closure', facsvc.count('slot.status=closure?FacilitySlotStatus.CLOSED:FacilitySlotStatus.AVAILABLE') >= 2)
check('appointment module registers the exception repository', 'ScheduleException' in facmodule)
check('exception entity registered in application and migration data source', 'ScheduleException' in app and 'ScheduleException' in ds)
check('exception repositories registered in doctor and facility modules', 'ScheduleException' in mod and 'ScheduleException' in schedmod)
check('migration creates exception table, time range constraint, and indexes', 'CREATE TABLE schedule_exceptions' in mg and 'endsAt" > "startsAt' in mg and 'CREATE INDEX' in mg)
check('V26 documentation covers doctor and facility APIs and booking safety', '## Doctor endpoints' in docs and '## Facility endpoints' in docs and 'not cancelled' in docs.lower())
for label,ok in checks: print(('PASS' if ok else 'FAIL')+' '+label)
print(f'{sum(ok for _,ok in checks)}/{len(checks)} checks passed')
raise SystemExit(0 if all(ok for _,ok in checks) else 1)
